// PDF support loads only when a Master Dispatch is imported. This keeps startup
// compatible with mobile browsers and lets the sign-in screen render first.
let getDocument,GlobalWorkerOptions,pdfReady;
async function ensurePdf(){
  if(!pdfReady)pdfReady=import('./pdf.min.mjs').then(pdf=>{
    getDocument=pdf.getDocument;
    GlobalWorkerOptions=pdf.GlobalWorkerOptions;
    GlobalWorkerOptions.workerSrc='./pdf.worker.min.mjs';
  });
  return pdfReady;
}
ensurePdf().catch(error=>console.error('PDF support failed to load:',error));
document.addEventListener('change',async e=>{
  if(e.target.id!=='dispatchFile'||!e.target.files[0])return;
  e.stopImmediatePropagation();
  const status=document.querySelector('#dispatchStatus');
  status.classList.remove('error');
  status.textContent='Reading dispatch PDF ';
  try{
    await ensurePdf();
    pendingDispatch=await parseMasterDispatch(e.target.files[0]);
    const existing=pendingDispatch.filter(job=>jobs.some(item=>item.workOrder===job.workOrder)).length;
    const fresh=pendingDispatch.length-existing;
    status.textContent=`Found ${fresh} new job${fresh===1?'':'s'}${existing?` and ${existing} existing job${existing===1?'':'s'} to update`:''}.`;
    showDispatchPreview();
  }catch(error){
    status.classList.add('error');
    status.textContent='Could not read this PDF. Please try the GoLime Master Dispatch again.';
    console.error('Master Dispatch import failed:',error);
  }
},true);
document.addEventListener('click',e=>{
  const action=e.target.closest('[data-action]');
  if(action?.dataset.action==='complete-job'){
    const job=jobs.find(item=>item.id===action.dataset.jobId);
    if(!job)return;
    job.status='Completed';
    save();
    showCompletedJobs();
    return;
  }
  if(e.target.closest('.filter')?.dataset.filter==='completed')setTimeout(showCompletedJobs,0);
});
document.addEventListener('click',e=>{
  const filter=e.target.closest('.filter');
  if(!filter)return;
  e.stopImmediatePropagation();
  if(filter.dataset.filter==='completed')showCompletedJobs();
  else{applyFilter(filter.dataset.filter);enableJobDeletion();}
},true);
