function extrasView(){app.append(template('extras-template'));const entries=jobs.filter(job=>job.source==='goline').flatMap(job=>(job.extras||[]).map((extra,index)=>({job,extra,index}))),totalExtras=entries.reduce((sum,item)=>sum+Number(item.extra.amount||0),0),workOrders=new Set(entries.map(item=>item.job.id)).size;document.querySelector('#extrasAmount').textContent=money(totalExtras);document.querySelector('#extrasStats').textContent=`${entries.length} extra charge${entries.length===1?'':'s'} across ${workOrders} work order${workOrders===1?'':'s'}.`;document.querySelector('#extrasSummary').innerHTML=entries.sort((a,b)=>b.job.date.localeCompare(a.job.date)).map(item=>`<article class="extra-summary-row"><div><strong>${esc(item.extra.description||'Extra charge')}</strong><span>${esc(item.job.workOrder||'No work order')} - ${new Date(item.job.date+'T12:00:00').toLocaleDateString('en-CA',{month:'short',day:'numeric',year:'numeric'})}</span><span>${esc(item.job.address||'Address not available')}</span></div><div style="display:flex;align-items:center;gap:7px"><strong>${money(item.extra.amount)}</strong><button class="secondary small" data-action="edit-job" data-job-id="${esc(item.job.id)}">Edit</button><button class="secondary small" style="color:#a22626;border-color:#efcaca" data-action="remove-extra" data-job-id="${esc(item.job.id)}" data-extra-index="${item.index}">Remove</button></div></article>`).join('')||empty('No extra charges have been recorded yet. Add one while editing a GoLime job.');}
function moneyView(){app.append(template('money-template'));renderMoneyLists()}
function dayGoLimeJobs(){return jobs.filter(j=>j.source==='goline'&&j.date===travelDate).sort(scheduleOrder)}
function updateTravelClaimButton(){const button=document.querySelector('#addTravelToClaim'),record=travelData[travelDate];if(!button)return;button.disabled=record?.farthestKm===undefined;button.textContent=record?.claimReady?'? Added to claims':'Add this day to claims'}
function travelView(){app.append(template('travel-template'));document.querySelector('#warehouseAddress').value=travelWarehouse;document.querySelector('#travelDate').value=travelDate;renderTravelDetails();updateTravelClaimButton();}
function renderTravelDetails(){const record=travelData[travelDate],dayJobs=dayGoLimeJobs(),routes=document.querySelector('#travelRoutes');document.querySelector('.save-indicator')?.remove();if(record?.farthestKm!==undefined){const calc=travelPay(record);document.querySelector('#travelAmount').textContent=money(calc.amount);document.querySelector('#farthestKm').textContent=`${calc.farthest.toFixed(1)} km`;document.querySelector('#reimbursableKm').textContent=`${calc.reimbursable.toFixed(1)} km`;document.querySelector('#travelFormula').textContent=travelCalculationDescription(record);if(record.manual)document.querySelector('#manualTravelKm').value=record.farthestKm;document.querySelector('#travelStatus').insertAdjacentHTML('afterend',`<p class="save-indicator">Saved for ${new Date(travelDate+'T12:00:00').toLocaleDateString('en-CA',{month:'long',day:'numeric',year:'numeric'})}<br>${travelCalculationDescription(record)}</p>`)}else{document.querySelector('#travelAmount').textContent=money(0);document.querySelector('#farthestKm').textContent=' ';document.querySelector('#reimbursableKm').textContent=' '}renderTravelHistory();if(!dayJobs.length){routes.innerHTML=empty('No GoLime jobs are scheduled for this date. Import the Master Dispatch first.');return}const routeByJob=Object.fromEntries((record?.routes||[]).map(r=>[r.jobId,r]));routes.innerHTML=dayJobs.map(j=>{const route=routeByJob[j.id];return `<article class="route-row"><div><strong>${esc(j.workOrder||'GoLime job')}</strong><span>${esc(j.address||'Address not available')}</span></div><span class="route-km">${route?.km!==undefined?`${Number(route.km).toFixed(1)} km`:route?.error||'Not calculated'}</span></article>`}).join('')}function renderTravelHistory(){const list=document.querySelector('#travelHistory'),entries=Object.entries(travelData).filter(([,r])=>r?.farthestKm!==undefined).sort(([a],[b])=>b.localeCompare(a));list.innerHTML=entries.map(([date,record])=>{const calc=travelPay(record);return `<article class="claim-summary-row" data-travel-date="${date}"><div><strong>${new Date(date+'T12:00:00').toLocaleDateString('en-CA',{weekday:'short',month:'short',day:'numeric',year:'numeric'})}</strong><span>${travelCalculationDescription(record)}</span></div><strong>${money(calc.amount)}</strong></article>`}).join('')||empty('No saved mileage records yet. Calculate travel pay for a job date to add one.');}function claimData(){const start=claimStart<=claimEnd?claimStart:claimEnd,end=claimStart<=claimEnd?claimEnd:claimStart,travel=Object.entries(travelData).filter(([date,record])=>date>=start&&date<=end&&record?.farthestKm!==undefined).sort(([a],[b])=>a.localeCompare(b)).map(([date,record])=>({date,record,calc:travelPay(record)})),extras=jobs.filter(job=>job.source==='goline'&&job.date>=start&&job.date<=end).flatMap(job=>(job.extras||[]).filter(extra=>extra.description||Number(extra.amount)).map(extra=>({job,extra}))),travelTotal=travel.reduce((sum,x)=>sum+x.calc.amount,0),extrasTotal=extras.reduce((sum,x)=>sum+Number(x.extra.amount||0),0),subtotal=travelTotal+extrasTotal;return {start,end,travel,extras,travelTotal,extrasTotal,subtotal,hst:hst(subtotal),totalWithHst:subtotal+hst(subtotal)}}
